// Construye un correo por organización a partir de lo que devolvió la consulta.
// Modo: "Run Once for All Items".
const cfg = $('Configuración').first().json;
const simulacro = cfg.modo_simulacro === true || cfg.modo_simulacro === 'true';
const MAX_FILAS = 8; // máximo de documentos listados en cada correo

// Escapa texto antes de meterlo en HTML (los títulos vienen de la base de datos).
const esc = (t) =>
  String(t ?? '').replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])
  );

// Reglas de severidad (explicadas en docs/decisiones.md):
//   ALTA  = algún sistema con menos de 30 % finalizado, o 5+ documentos estancados
//   MEDIA = algún sistema bajo el umbral configurado, o 3-4 documentos estancados
//   BAJA  = el resto
function calcularSeveridad(estancados, bajos) {
  const peor = bajos.length ? Math.min(...bajos.map((b) => Number(b.porcentaje))) : 100;
  if (peor < 30 || estancados.length >= 5) return 'ALTA';
  if (bajos.length > 0 || estancados.length >= 3) return 'MEDIA';
  return 'BAJA';
}

const COLOR = { ALTA: '#c0392b', MEDIA: '#e67e22', BAJA: '#2e86c1' };

return $input.all().map((item, indice) => {
  const f = item.json;
  const estancados = f.documentos_estancados ?? [];
  const bajos = f.sistemas_bajo_umbral ?? [];
  const severidad = calcularSeveridad(estancados, bajos);
  const destinatario = simulacro ? cfg.correo_prueba : f.correo_contacto;

  const filasSistemas = bajos
    .map(
      (b) =>
        `<tr><td style="padding:6px 10px"><b>${esc(b.sistema)}</b></td>` +
        `<td style="padding:6px 10px">${b.finalizados} de ${b.total} documentos finalizados</td>` +
        `<td style="padding:6px 10px;color:${COLOR[severidad]}"><b>${b.porcentaje} %</b></td></tr>`
    )
    .join('');

  const filasDocs = estancados
    .slice(0, MAX_FILAS)
    .map(
      (d) =>
        `<tr><td style="padding:6px 10px">${esc(d.sistema)}</td>` +
        `<td style="padding:6px 10px">${esc(d.titulo)}</td>` +
        `<td style="padding:6px 10px">${
          d.estado === 'BORRADOR' ? 'Borrador sin cambios hace' : 'Sin iniciar hace'
        } ${d.dias} días</td></tr>`
    )
    .join('');
  const resto = estancados.length - MAX_FILAS;

  const html =
    `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;color:#222">` +
    (simulacro
      ? `<p style="background:#fff3cd;padding:10px;border-radius:6px">SIMULACRO: este correo se enviaría a <b>${esc(
          f.correo_contacto
        )}</b>. Se redirigió a la dirección de prueba.</p>`
      : '') +
    `<h2 style="margin-bottom:4px">Alerta de cumplimiento SST / PESV</h2>` +
    `<p style="margin-top:0"><b>${esc(f.organizacion)}</b> · ` +
    `severidad <b style="color:${COLOR[severidad]}">${severidad}</b></p>` +
    (bajos.length
      ? `<h3>Sistemas por debajo del ${cfg.umbral_cumplimiento} % de cumplimiento</h3>` +
        `<table style="border-collapse:collapse;width:100%">${filasSistemas}</table>`
      : '') +
    (estancados.length
      ? `<h3>Documentos que requieren atención (${estancados.length})</h3>` +
        `<table style="border-collapse:collapse;width:100%;font-size:14px">${filasDocs}</table>` +
        (resto > 0 ? `<p>… y ${resto} más.</p>` : '')
      : '') +
    `<p style="color:#666;font-size:12px;margin-top:24px">Mensaje automático generado con n8n. ` +
    `Un documento está estancado si lleva ${cfg.dias_borrador}+ días en borrador sin cambios ` +
    `o ${cfg.dias_no_iniciado}+ días sin iniciarse.</p></div>`;

  return {
    json: {
      tenant_id: Number(f.tenant_id),
      organizacion: f.organizacion,
      severidad,
      destinatario,
      correo_remitente: cfg.correo_remitente,
      es_simulacro: simulacro,
      asunto: `${simulacro ? '[SIMULACRO] ' : ''}Alerta ${severidad} SST/PESV: ${f.organizacion}`,
      html,
      resumen: {
        documentos_estancados: estancados.length,
        sistemas_bajo_umbral: bajos,
      },
    },
    pairedItem: { item: indice },
  };
});

// Decide el estado del envío (ENVIADA o ERROR) para guardarlo en la bitácora.
// Modo: "Run Once for Each Item".
// El nodo de correo tiene "On Error: Continue", así que si falla para una
// organización no se detiene todo: llega aquí un ítem con el campo "error".
const base = $('Construir mensaje').item.json;
const err = $json.error;
const fallo = err !== undefined && err !== null && err !== '';

return {
  json: {
    tenant_id: base.tenant_id,
    organizacion: base.organizacion,
    severidad: base.severidad,
    destinatario: base.destinatario,
    es_simulacro: base.es_simulacro,
    resumen: base.resumen,
    estado: fallo ? 'ERROR' : 'ENVIADA',
    // Cadena vacía (no null) y la consulta usa NULLIF: evita problemas con nulos en los parámetros.
    detalle_error: fallo ? String(err.message ?? err).slice(0, 500) : '',
  },
};

