INSERT INTO alertas.bitacora
    (tenant_id, severidad, resumen, destinatario, es_simulacro, estado, detalle_error)
VALUES ($1::int, $2, $3::jsonb, $4, $5::boolean, $6, NULLIF($7::text, ''));

