// Arma el resumen de la ejecución para el administrador (se envía por Telegram).
// Modo: "Run Once for All Items".
const cfg = $('Configuración').first().json;
const simulacro = cfg.modo_simulacro === true || cfg.modo_simulacro === 'true';
const filas = $('Preparar registro').all().map((i) => i.json);

const enviadas = filas.filter((f) => f.estado === 'ENVIADA').length;
const errores = filas.length - enviadas;
const lineas = filas.map(
  (f) => `- ${f.organizacion}: ${f.severidad} (${f.estado === 'ENVIADA' ? 'enviada' : 'ERROR'})`
);

const texto = [
  `Alertas SST/PESV - modo ${simulacro ? 'SIMULACRO' : 'REAL'}`,
  `Organizaciones alertadas: ${filas.length} | enviadas: ${enviadas} | con error: ${errores}`,
  '',
  ...lineas,
].join('\n');

return [{ json: { texto } }];
